import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { recordedInvocations } from "../src/execute";
import { createFixture, wardLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the hooks.json and wrapper generated by the real `ward integrate codex
// --guard-approved-specs` against the Codex 0.163.0 contract, read from codex-rs at rust-v0.163.0:
// - config/src/hook_config.rs: HooksFile is deny_unknown_fields ({description, hooks}); events are
//   matcher groups of tagged handlers.
// - hooks/src/engine/matcher.rs: a matcher of letters, digits, '_' and '|' is an exact-name list.
// - hooks/src/engine/command_runner.rs: commands run through the shell in the session's cwd.
// - core: Bash and apply_patch send tool_input.command (the patch text for apply_patch).
// The real Ward answers behind a recording wrapper.

const EVENTS = [
  "PreToolUse",
  "PermissionRequest",
  "PostToolUse",
  "PreCompact",
  "PostCompact",
  "SessionStart",
  "SessionEnd",
  "UserPromptSubmit",
  "SubagentStart",
  "SubagentStop",
  "Stop",
  "Interrupt",
];

/** Applies Codex 0.163.0's hooks.json parsing rules; returns the reasons Codex would reject it. */
function codexRejects(json: string): string[] {
  let config: any;
  try {
    config = JSON.parse(json);
  } catch {
    return ["not JSON"];
  }
  const errors: string[] = [];
  for (const key of Object.keys(config)) {
    if (key !== "description" && key !== "hooks") errors.push(`unknown field ${key}`);
  }
  for (const [event, groups] of Object.entries(config.hooks ?? {})) {
    if (!EVENTS.includes(event)) continue; // ignored by serde, not an error
    for (const group of groups as any[]) {
      const handlers = group.hooks ?? [];
      if (handlers.length === 0) errors.push(`${event} group has no handlers`);
      for (const handler of handlers) {
        if (handler.type !== "command" || typeof handler.command !== "string") errors.push(`${event} handler is not a command`);
      }
    }
  }
  return errors;
}

function matcherMatches(matcher: string | undefined, tool: string): boolean {
  if (!matcher || matcher === "*") return true;
  if (/^[A-Za-z0-9_|]+$/.test(matcher)) return matcher.split("|").includes(tool);
  return new RegExp(matcher).test(tool);
}

let fixture: Fixture;
let unguarded: Fixture;
let config: any;
let log: string;
let bin: string;

beforeAll(async () => {
  const ward = wardLauncher(process.env)!;
  fixture = await createFixture({ harness: "codex", guard: true, ward });
  unguarded = await createFixture({ harness: "codex", guard: false, ward });
  config = JSON.parse(readFileSync(join(fixture.root, ".codex/hooks.json"), "utf8"));
  bin = join(dirname(fixture.root), "ward-bin");
  log = join(dirname(fixture.root), "ward-log");
  writeRecordingWrapper(bin, log, ward);
  for (const f of [fixture, unguarded]) {
    await run(["/usr/bin/git", "init", "-q"], { cwd: f.root, env: f.env, timeoutMs: 30_000 });
    mkdirSync(join(f.root, "src/main/java"), { recursive: true });
  }
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  writeFileSync(join(fixture.root, "openspec-stub.sh"), '#!/bin/sh\nif [ -f SPEC_FAIL ]; then echo "add-x: missing scenario"; exit 1; fi\n');
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
  const toml = join(fixture.root, "ward.toml");
  writeFileSync(toml, `${readFileSync(toml, "utf8")}\n[quality-gates.openspec]\nenabled = true\ncommand = ["./openspec-stub.sh"]\n`);
});

afterAll(() => {
  fixture?.cleanup();
  unguarded?.cleanup();
  cleanupOwnedProcesses();
});

const handler = (event: string, tool?: string, cfg = config) =>
  (cfg.hooks[event] as any[]).filter((group) => tool === undefined || matcherMatches(group.matcher, tool)).flatMap((group) => group.hooks);

/** Runs a handler like Codex: through the shell, in the session cwd, with the event on stdin. */
async function launch(f: Fixture, command: string, payload: unknown, cwd = join(f.root, "src/main/java")) {
  const before = recordedInvocations(log).length;
  const env = { ...f.env, PATH: `${bin}:${SYSTEM_PATH}` };
  const stdin = typeof payload === "string" ? payload : JSON.stringify({ session_id: "s", turn_id: "t", cwd, model: "m", permission_mode: "default", ...(payload as object) });
  const result = await run(["/bin/sh", "-c", command], { cwd, env, stdin, timeoutMs: 60_000 });
  return { result, invocations: recordedInvocations(log).slice(before) };
}

const pre = (tool: string, input: Record<string, unknown>, cwd?: string) =>
  launch(fixture, handler("PreToolUse", tool)[0].command, { hook_event_name: "PreToolUse", tool_name: tool, tool_use_id: "u", tool_input: input }, cwd);

describe("generated hooks.json against the Codex 0.163.0 schema", () => {
  test("Codex accepts the generated configuration", () => {
    expect(codexRejects(readFileSync(join(fixture.root, ".codex/hooks.json"), "utf8"))).toEqual([]);
  });

  test("negative control: Codex rejects the legacy configuration", () => {
    expect(codexRejects(readFileSync(join(import.meta.dir, "legacy-hooks.json.txt"), "utf8"))).toEqual([
      "unknown field wardOwnership",
      "PostToolUse group has no handlers",
    ]);
  });

  test("the guard runs before shell and patch calls; checks run after patches and at Stop", () => {
    expect(handler("PreToolUse", "Bash").length).toBe(1);
    expect(handler("PreToolUse", "apply_patch").length).toBe(1);
    expect(handler("PreToolUse", "read_file").length).toBe(0);
    expect(handler("PostToolUse", "apply_patch").length).toBe(1);
    expect(handler("PostToolUse", "Bash").length).toBe(0);
    expect(handler("Stop").length).toBe(1);
  });

  test("the ownership marker is in the description field", () => {
    expect(config.description).toContain("ward-owned: codex-native-hooks v1");
  });
});

describe("hook execution from a subdirectory of the repository", () => {
  test("a relative path that resolves outside approved specs from the session cwd is allowed", async () => {
    const { result } = await pre("Bash", { command: "rm openspec/specs/auth/spec.md" });
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });

  test("the guard passes a harmless shell command", async () => {
    const { result, invocations } = await pre("Bash", { command: "ls src" });
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "codex", "--guard-approved-specs", "--event-stdin"]]);
    expect(invocations[0].cwd.endsWith("/project")).toBe(true);
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });

  test("the guard denies a protected shell command with the approved-spec reason", async () => {
    // Codex runs Bash in the session cwd, so the session is at the repository root here.
    const { result } = await pre("Bash", { command: "rm openspec/specs/auth/spec.md" }, fixture.root);
    const decision = JSON.parse(result.stdout).hookSpecificOutput;
    expect(decision).toMatchObject({ hookEventName: "PreToolUse", permissionDecision: "deny" });
    expect(decision.permissionDecisionReason).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard denies a patch to an approved spec and allows one to an active change", async () => {
    const patch = (path: string) => `*** Begin Patch\n*** Update File: ${path}\n@@\n-old\n+new\n*** End Patch\n`;
    // Patch paths are relative to the session cwd, which is the repository root here.
    const denied = await pre("apply_patch", { command: patch("openspec/specs/auth/spec.md") }, fixture.root);
    expect(JSON.parse(denied.result.stdout).hookSpecificOutput.permissionDecision).toBe("deny");
    const allowed = await pre("apply_patch", { command: patch("openspec/changes/add-x/tasks.md") }, fixture.root);
    expect([allowed.result.exitCode, allowed.result.stdout.trim()]).toEqual([0, ""]);
  });

  test("uninspectable input is denied", async () => {
    const { result } = await launch(fixture, handler("PreToolUse", "Bash")[0].command, "{not json");
    expect(JSON.parse(result.stdout).hookSpecificOutput.permissionDecision).toBe("deny");
  });

  test("a failing check after a patch exits 2 with the findings on stderr", async () => {
    writeFileSync(join(fixture.root, "FAIL"), "");
    try {
      const { result, invocations } = await launch(fixture, handler("PostToolUse", "apply_patch")[0].command, {
        hook_event_name: "PostToolUse",
        tool_name: "apply_patch",
        tool_input: { command: "*** Begin Patch" },
        tool_response: "ok",
      });
      expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "codex", "--event-stdin"]]);
      expect(result.exitCode).toBe(2);
      expect(result.stderr).toContain("Ward quality findings");
    } finally {
      rmSync(join(fixture.root, "FAIL"), { force: true });
    }
  });

  test("Stop findings continue the turn once with decision block, then only report", async () => {
    writeFileSync(join(fixture.root, "SPEC_FAIL"), "");
    try {
      const stop = (active: boolean) => launch(fixture, handler("Stop")[0].command, { hook_event_name: "Stop", stop_hook_active: active, last_assistant_message: "done" });
      const first = await stop(false);
      expect(first.result.exitCode).toBe(0);
      expect(JSON.parse(first.result.stdout)).toMatchObject({ decision: "block" });
      expect(JSON.parse(first.result.stdout).reason).toContain("missing scenario");
      const second = await stop(true);
      expect([second.result.exitCode, second.result.stdout.trim()]).toEqual([0, ""]);
      expect(second.result.stderr).toContain("missing scenario");
    } finally {
      rmSync(join(fixture.root, "SPEC_FAIL"), { force: true });
    }
  });

  test("a clean Stop is silent", async () => {
    const { result } = await launch(fixture, handler("Stop")[0].command, { hook_event_name: "Stop", stop_hook_active: false });
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });

  test("with the guard disabled, the pre phase allows without running Ward", async () => {
    const unguardedConfig = JSON.parse(readFileSync(join(unguarded.root, ".codex/hooks.json"), "utf8"));
    const { result, invocations } = await launch(unguarded, handler("PreToolUse", "Bash", unguardedConfig)[0].command, {
      hook_event_name: "PreToolUse",
      tool_name: "Bash",
      tool_input: { command: "rm openspec/specs/auth/spec.md" },
    });
    expect([result.exitCode, result.stdout.trim(), invocations.length]).toEqual([0, "", 0]);
  });
});
